// Gerbang masuk: pastikan payload minimal ada sebelum apa pun dikerjakan.
const body = $json.body || {};
const results = body.results;

const sessionId = body.session_id || null;
const isArray = Array.isArray(results);
const count = isArray ? results.length : 0;

let valid = true;
let reason = null;

if (!sessionId) { valid = false; reason = 'session_id_missing'; }
else if (!isArray) { valid = false; reason = 'results_not_an_array'; }
else if (count === 0) { valid = false; reason = 'results_empty'; }

return [{ json: {
  valid,
  invalid_reason: reason,
  session_id: sessionId,
  control_count: count,
  results: isArray ? results : [],
  locale: body.locale === 'id' ? 'id' : 'en',
}}];

// Ringkas hasil asesmen menjadi statistik agregat.
// Tujuan: LLM tidak perlu membaca data mentah, cukup gambaran menyeluruh.
// Efeknya: token turun drastis, dan hasilnya jauh lebih konsisten.

const src = $json;
const rows = src.results || [];

// Skema hasil asesmen bisa berbeda-beda penamaannya.
// Fungsi ini mencoba beberapa nama kolom yang umum dipakai.
function pick(obj, keys) {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return null;
}

const K_MATURITY = ['maturity_level', 'maturity_rating', 'maturity', 'level', 'score'];
const K_STATUS   = ['compliance_status', 'compliance', 'status'];
const K_CONTROL  = ['control_code', 'control_id', 'code', 'clause', 'clausa', 'control'];
const K_DOMAIN   = ['domain', 'category', 'theme', 'annex', 'group'];
const K_NOTES    = ['assessment_notes', 'notes', 'note', 'catatan', 'description'];
const K_EVIDENCE = ['evidence_file', 'evidence', 'bukti', 'attachment'];

function hasEvidence(v) {
  if (v === null || v === undefined) return false;
  if (Array.isArray(v)) return v.length > 0;
  if (typeof v === 'string') return v.trim().length > 0;
  if (typeof v === 'object') return Object.keys(v).length > 0;
  return Boolean(v);
}

const maturityCount = {};
const statusCount = {};
const domainStats = {};
const lowMaturity = [];

let withNotes = 0;
let withEvidence = 0;
let withEither = 0;
let maturitySum = 0;
let maturityNumeric = 0;

const detected = { maturity: null, status: null, control: null, domain: null };

for (const r of rows) {
  const mRaw = pick(r, K_MATURITY);
  const sRaw = pick(r, K_STATUS);
  const cRaw = pick(r, K_CONTROL);
  const dRaw = pick(r, K_DOMAIN);
  const nRaw = pick(r, K_NOTES);
  const eRaw = pick(r, K_EVIDENCE);

  if (!detected.maturity) detected.maturity = K_MATURITY.find(k => r[k] !== undefined) || null;
  if (!detected.status)   detected.status   = K_STATUS.find(k => r[k] !== undefined) || null;
  if (!detected.control)  detected.control  = K_CONTROL.find(k => r[k] !== undefined) || null;
  if (!detected.domain)   detected.domain   = K_DOMAIN.find(k => r[k] !== undefined) || null;

  const mKey = mRaw === null ? 'unrated' : String(mRaw);
  const sKey = sRaw === null ? 'unknown' : String(sRaw);

  maturityCount[mKey] = (maturityCount[mKey] || 0) + 1;
  statusCount[sKey] = (statusCount[sKey] || 0) + 1;

  const mNum = Number(mRaw);
  if (!Number.isNaN(mNum) && mRaw !== null && mRaw !== '') {
    maturitySum += mNum;
    maturityNumeric += 1;
  }

  const dKey = dRaw ? String(dRaw) : 'uncategorized';
  if (!domainStats[dKey]) domainStats[dKey] = { total: 0, low: 0, sum: 0, numeric: 0 };
  domainStats[dKey].total += 1;
  if (!Number.isNaN(mNum) && mRaw !== null && mRaw !== '') {
    domainStats[dKey].sum += mNum;
    domainStats[dKey].numeric += 1;
    if (mNum <= 2) domainStats[dKey].low += 1;
  }

  if (!Number.isNaN(mNum) && mNum <= 2) {
    lowMaturity.push({
      control: cRaw ? String(cRaw) : '(tanpa kode)',
      domain: dKey,
      maturity: mNum,
      status: sKey,
    });
  }

  const n = nRaw && String(nRaw).trim().length > 0;
  const e = hasEvidence(eRaw);
  if (n) withNotes += 1;
  if (e) withEvidence += 1;
  if (n || e) withEither += 1;
}

const total = rows.length;
const pct = v => total === 0 ? 0 : Math.round((v / total) * 1000) / 10;

// Tingkat keyakinan dihitung DETERMINISTIK di sini, bukan oleh LLM.
// Ini aritmetika, bukan penilaian — tidak boleh diserahkan ke model.
const supportPct = pct(withEither);
let confidenceLevel;
if (supportPct >= 70) confidenceLevel = 'well_supported';
else if (supportPct >= 30) confidenceLevel = 'partially_supported';
else confidenceLevel = 'limited';

const domainSummary = Object.entries(domainStats)
  .map(([name, s]) => ({
    domain: name,
    total: s.total,
    low_maturity_count: s.low,
    avg_maturity: s.numeric ? Math.round((s.sum / s.numeric) * 100) / 100 : null,
  }))
  .sort((a, b) => b.low_maturity_count - a.low_maturity_count);

return [{ json: {
  session_id: src.session_id,
  locale: src.locale || 'en',
  aggregate: {
    total_controls: total,
    average_maturity: maturityNumeric ? Math.round((maturitySum / maturityNumeric) * 100) / 100 : null,
    maturity_distribution: maturityCount,
    compliance_distribution: statusCount,
    domain_summary: domainSummary,
    low_maturity_controls: lowMaturity.slice(0, 40),
    low_maturity_total: lowMaturity.length,
    supporting_info: {
      controls_with_notes: withNotes,
      controls_with_evidence: withEvidence,
      controls_with_either: withEither,
      support_coverage_percent: supportPct,
      confidence_level: confidenceLevel,
    },
  },
  _schema_detected: detected,
}}];

// Bersihkan, parse, lalu susun DUA versi bahasa sekaligus dari satu respons model.
const prep = $('Prepare LLM Request1').first().json;

let raw = '';
try { raw = $json.choices[0].message.content || ''; } catch (e) { raw = ''; }

// Buang blok penalaran dan pagar kode kalau model tetap menambahkannya.
let clean = raw
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/^\s*```(?:json)?/i, '')
  .replace(/```\s*$/i, '')
  .trim();

// Ambil objek JSON pertama kalau masih ada teks pembungkus.
function extractJson(s) {
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(s.slice(start, end + 1)); } catch (e) { return null; }
}

const parsed = extractJson(clean);
const parseOk = parsed !== null;

const LABELS = {
  en: { conclusion: 'Overall Assessment Conclusion', risk: 'Overall Risk Areas', recs: 'Executive Strategic Recommendations', confidence: 'Assessment Confidence', failed: 'Failed to generate AI summary.' },
  id: { conclusion: 'Kesimpulan Asesmen Keseluruhan', risk: 'Area Risiko Utama', recs: 'Rekomendasi Strategis Eksekutif', confidence: 'Tingkat Keyakinan Asesmen', failed: 'Gagal menghasilkan ringkasan AI.' },
};

function pick(field, lang) {
  if (!field) return null;
  if (typeof field === 'string') return field;
  return field[lang] ?? null;
}

function section(title, body) {
  if (!body) return '';
  return '## ' + title + '\n\n' + String(body).trim() + '\n\n';
}

function buildPretty(lang) {
  if (!parseOk) return clean;
  const labels = LABELS[lang];
  const recsField = pick(parsed.executive_strategic_recommendations, lang);
  const recs = Array.isArray(recsField) ? recsField : (recsField ? [recsField] : []);
  let pretty =
    section(labels.conclusion, pick(parsed.overall_assessment_conclusion, lang)) +
    section(labels.risk, pick(parsed.overall_risk_areas, lang)) +
    (recs.length
      ? '## ' + labels.recs + '\n\n' +
        recs.map((r, i) => (i + 1) + '. ' + String(r).trim()).join('\n') + '\n\n'
      : '') +
    section(labels.confidence, pick(parsed.assessment_confidence, lang));
  return pretty.trim();
}

const prettyEn = buildPretty('en');
const prettyId = buildPretty('id');

const usableEn = prettyEn && prettyEn.length >= 50;
const usableId = prettyId && prettyId.length >= 50;

return [{ json: {
  session_id: prep.session_id,
  status: (usableEn || usableId) ? 'ok' : 'failed',
  ai_summary_en: usableEn ? prettyEn : LABELS.en.failed,
  ai_summary_id: usableId ? prettyId : LABELS.id.failed,
  ai_summary_json: parseOk ? JSON.stringify(parsed) : null,
  parse_ok: parseOk,
  confidence_level: prep.aggregate.supporting_info.confidence_level,
  support_coverage_percent: prep.aggregate.supporting_info.support_coverage_percent,
  total_controls: prep.aggregate.total_controls,
  error_reason: (usableEn || usableId) ? null : (parseOk ? 'summary_too_short' : 'model_output_unparseable'),
}}];

// Jalur gagal. Yang penting: Laravel TETAP menerima callback,
// supaya sesi tidak menggantung selamanya di status "sedang diproses".
let sessionId = null;
try { sessionId = $('Validate Payload').first().json.session_id; } catch (e) {}
if (!sessionId) {
  try { sessionId = $('Webhook: Audit Summary').first().json.body.session_id; } catch (e) {}
}

const j = $json || {};
let reason = j.invalid_reason
  || (j.error && j.error.message)
  || j.message
  || 'unknown_error';

return [{ json: {
  session_id: sessionId,
  status: 'failed',
  ai_summary_en: 'Failed to generate AI summary.',
  ai_summary_id: 'Gagal menghasilkan ringkasan AI.',
  ai_summary_json: null,
  parse_ok: false,
  confidence_level: null,
  support_coverage_percent: null,
  total_controls: null,
  error_reason: String(reason).slice(0, 300),
}}];
